#include <vector>
#include <algorithm>

void remove_first_instance(std::vector<int>& coll, int val) {
    // 1. Locate the value
    std::vector<int>::iterator pos;
    pos = std::find(coll.begin(), coll.end(), val);

    // 2. Validate and Erase
    if (pos != coll.end()) {
        coll.erase(pos); // O(N) operation
    }
    // If erase occurred, 'pos' is now invalidated.
}
